// 1. ดึงข้อมูลคำถามและ Metadata
const chatInputData = $('When chat message received').first().json;
const userQuery = chatInputData.chatInput || chatInputData.query || '';
const metadata = chatInputData.metadata || {};

// 2. ดึงคำตอบและ Intermediate Steps จาก AI Agent
const agentData = $json;
const botResponse = agentData.output || agentData.text || '';

// 3. สกัดแหล่งข้อมูลอ้างอิงจาก intermediateSteps (Evidence Grounding)
function extractSources(obj, found = []) {
  if (!obj) return found;
  if (Array.isArray(obj)) {
    for (const item of obj) extractSources(item, found);
  } else if (typeof obj === 'object') {
    const meta = obj.metadata || obj;
    const fileName = meta.file_name || meta.file || meta.source;
    const pageNum = meta.pageNumber || meta.page_number || (meta.loc && meta.loc.pageNumber);
    if (fileName && typeof fileName === 'string') {
      found.push({
        fileName: fileName.trim(),
        pageNumber: (pageNum !== undefined && pageNum !== null && !isNaN(Number(pageNum))) ? Number(pageNum) : null
      });
    }
    for (const key of Object.keys(obj)) {
      if (typeof obj[key] === 'object' || Array.isArray(obj[key])) {
        extractSources(obj[key], found);
      } else if (typeof obj[key] === 'string' && (obj[key].startsWith('{') || obj[key].startsWith('['))) {
        try { extractSources(JSON.parse(obj[key]), found); } catch (_) {}
      }
    }
  } else if (typeof obj === 'string') {
    try {
      extractSources(JSON.parse(obj), found);
    } catch (_) {
      const matchJson = obj.match(/\{[^{}]*(?:file_name|pageNumber|page_number|loc)[^{}]*\}/g);
      if (matchJson) {
        for (const m of matchJson) {
          try { extractSources(JSON.parse(m), found); } catch (_) {}
        }
      }
    }
  }
  return found;
}

// 4. จำแนกประเภทคำถาม (Smart Intent Detection)
function detectIntent(q) {
  const queryLower = (q || '').toLowerCase();
  if (/^(สวัสดี|หวัดดี|ดีครับ|ดีค่ะ|hello|hi|hey)/i.test(queryLower) && queryLower.length < 30) {
    return 'greeting';
  }
  if (queryLower.includes('บังคับก่อน') || queryLower.includes('prerequisite') || queryLower.includes('prereq') || queryLower.includes('เรียนก่อน') || queryLower.includes('ผ่านมาก่อน') || queryLower.includes('ติด f') || queryLower.includes('ตัวต่อ')) {
    return 'prerequisite_check';
  }
  if (queryLower.includes('เกรด') || queryLower.includes('gpa') || queryLower.includes('gpax') || queryLower.includes('หน่วยกิต') || queryLower.includes('จบการศึกษา')) {
    return 'gpa_inquiry';
  }
  if (queryLower.includes('เปรียบเทียบ') || queryLower.includes('เทียบหลักสูตร') || queryLower.includes('ต่างกัน')) {
    return 'curriculum_compare';
  }
  if (queryLower.includes('แผนการเรียน') || queryLower.includes('สหกิจ') || queryLower.includes('ฝึกงาน') || queryLower.includes('coop') || /ปี\s*[1-4]\s*(เทอม|\/)/.test(queryLower)) {
    return 'study_plan';
  }
  if (queryLower.includes('ลงทะเบียน') || queryLower.includes('แนะนำวิชา') || queryLower.includes('ควรลง') || queryLower.includes('วิชาเลือก')) {
    return 'registration_advice';
  }
  if (queryLower.includes('ภาควิชา') || queryLower.includes('ตึก') || queryLower.includes('อาคาร') || queryLower.includes('อาจารย์') || queryLower.includes('ติดต่อ')) {
    return 'general_question';
  }
  return 'course_info';
}

function checkIsSuccess(resp) {
  const text = (resp || '').trim();
  if (!text) return false;
  const fallbackIndicators = ['ไม่พบข้อมูล', 'ไม่มีข้อมูลในระบบ', 'ไม่สามารถตอบ', 'ไม่สามารถให้ข้อมูล', 'ขออภัย ไม่พบ', 'ขออภัยครับ ไม่พบ', 'ขออภัยค่ะ ไม่พบ'];
  for (const phrase of fallbackIndicators) {
    if (text.includes(phrase)) return false;
  }
  if (text.startsWith('ขออภัย') && text.length < 80) return false;
  return true;
}

const intent = detectIntent(userQuery);
const isSuccess = checkIsSuccess(botResponse);

// 5. ประกอบบล็อกอ้างอิงเฉพาะเมื่อมีแหล่งข้อมูลจริงและไม่ใช่คำทักทาย
let finalBotResponse = botResponse;
if (intent !== 'greeting' && isSuccess && agentData.intermediateSteps) {
  const rawSources = extractSources(agentData.intermediateSteps);
  const uniqueSources = new Map();
  for (const s of rawSources) {
    const key = `${s.fileName}__${s.pageNumber ?? 'none'}`;
    if (!uniqueSources.has(key)) {
      uniqueSources.set(key, s);
    }
  }

  if (uniqueSources.size > 0) {
    const fileGroups = new Map();
    for (const s of uniqueSources.values()) {
      if (!fileGroups.has(s.fileName)) fileGroups.set(s.fileName, new Set());
      if (s.pageNumber !== null && !isNaN(s.pageNumber)) {
        fileGroups.get(s.fileName).add(s.pageNumber);
      }
    }

    const citationLines = [];
    for (const [fileName, pagesSet] of fileGroups.entries()) {
      const pages = Array.from(pagesSet).sort((a, b) => a - b);
      if (pages.length > 0) {
        citationLines.push(`• ${fileName} (หน้าที่ ${pages.join(', ')})`);
      } else {
        citationLines.push(`• ${fileName}`);
      }
    }

    if (citationLines.length > 0) {
      finalBotResponse = `${botResponse}\n\n📌 **แหล่งข้อมูลอ้างอิง:**\n${citationLines.join('\n')}`;
    }
  }
}

// 6. ส่งค่าออกไปให้ Node "บันทึกลง Firebase" และ "Return Output"
return {
  json: {
    sessionId: metadata.sessionId || `sess_${Date.now()}`,
    userId: metadata.userId || 'guest',
    userName: metadata.userName || 'Guest',
    userRole: metadata.role || 'guest',
    studentId: metadata.studentId || '',
    query: userQuery,
    response: finalBotResponse,
    intent: intent,
    isSuccess: isSuccess,
    responseTimeMs: 850,
    channel: metadata.channel || 'web',
    timestamp: new Date().toISOString(),
    output: finalBotResponse
  }
};
